    pg_get_serial_sequence('fixed.ui_table_columns', 'ui_tbl_clm_id'),
    (SELECT GREATEST(COALESCE(MAX(ui_tbl_clm_id), 0), 1) FROM fixed.ui_table_columns),
    true
);

COMMIT;
